const tabId = 730410078;
const gameDates = await browserjs(tabId, async () => {
  // Let's search from September 2026 backwards to find the most recent date with an NBA game
  // Let's check June 2026 and May 2026, and also July 2026
  async function checkDate(dateStr) {
    try {
      const res = await fetch(`https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard?dates=${dateStr}`);
      const data = await res.json();
      if (data.events && data.events.length > 0) {
        return {
          date: dateStr,
          events: data.events.map(e => ({
            id: e.id,
            name: e.name,
            shortName: e.shortName,
            status: e.status?.type?.description,
            completed: e.status?.type?.completed,
            date: e.date,
            links: e.links?.map(l => ({ rel: l.rel, href: l.href }))
          }))
        };
      }
    } catch(e) {}
    return null;
  }

  // Check June 1 to June 30
  const juneResults = [];
  for (let d = 30; d >= 1; d--) {
    const dStr = `202606${d < 10 ? '0' + d : d}`;
    const res = await checkDate(dStr);
    if (res) juneResults.push(res);
  }

  // Also check July 1 to July 31
  const julyResults = [];
  for (let d = 31; d >= 1; d--) {
    const dStr = `202607${d < 10 ? '0' + d : d}`;
    const res = await checkDate(dStr);
    if (res) julyResults.push(res);
  }

  // Also check May 15 to May 31
  const mayResults = [];
  for (let d = 31; d >= 15; d--) {
    const dStr = `202605${d < 10 ? '0' + d : d}`;
    const res = await checkDate(dStr);
    if (res) mayResults.push(res);
  }

  return { julyResults, juneResults, mayResults };
});

