const playerInspection = await browserjs(tabId, () => {
  function findVideos(root) {
    let list = Array.from(root.querySelectorAll('video'));
    const all = root.querySelectorAll('*');
    for (const el of all) {
      if (el.shadowRoot) {
        list = list.concat(findVideos(el.shadowRoot));
      }
    }
    return list;
  }
  const videos = findVideos(document);
  return videos.map(v => ({
    tagName: v.tagName,
    paused: v.paused,
    currentTime: v.currentTime,
    duration: v.duration,
    src: v.src,
    currentSrc: v.currentSrc,
    readyState: v.readyState,
    parentElement: v.parentElement?.tagName,
    shadowHost: v.getRootNode()?.host?.tagName
  }));
});
