  // Let's test a few dates or fetch scoreboard for June 2026
  const results = [];
  for (let m = 6; m >= 1; m--) {
    const dStr = `20260${m}15`;
    const res = await fetch(`https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard?dates=${dStr}`);
    const data = await res.json();
    results.push({
      month: m,
      eventsCount: data.events?.length,
      firstEvent: data.events?.[0]?.name,
      status: data.events?.[0]?.status?.type?.description
    });
  }
  return results;
});
